<script>
(()=>{'use strict';const toggle=document.querySelector('[data-toggle-password]');const password=document.getElementById('password');toggle?.addEventListener('click',()=>{if(!password)return;const visible=password.type==='text';password.type=visible?'password':'text';toggle.setAttribute('aria-label',visible?'Show password':'Hide password');toggle.setAttribute('aria-pressed',String(!visible));const icon=toggle.querySelector('i');if(icon)icon.className=visible?'ti ti-eye':'ti ti-eye-off'});document.querySelector('[data-login-error]')?.focus();document.querySelector('[data-login-form]')?.addEventListener('submit',function(event){if(!this.checkValidity())return;const button=this.querySelector('[data-login-submit]');if(!button||button.disabled){event.preventDefault();return}button.disabled=true;button.setAttribute('aria-busy','true');button.querySelector('[data-login-submit-label]').textContent='Signing in…';button.querySelector('[data-login-submit-arrow]')?.classList.add('d-none');button.querySelector('[data-login-submit-spinner]')?.classList.remove('d-none')})})();
</script>
